import { readFile, readdir, writeFile } from 'node:fs/promises';
import { resolve, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

// Read maintained source/configuration only, never local databases or private data.
const root = fileURLToPath(new URL('../', import.meta.url));
const lines = ['# Source inventory', '',
  'Generated by `npm run inventory`. This static map does not prove that services work. No application code is imported or started.', ''];
for (const group of ['packages', 'apps', 'services']) {
  for (const entry of await readdir(resolve(root, group), { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const folder = `${group}/${entry.name}`;
    let manifest;
    try { manifest = JSON.parse(await readFile(resolve(root, folder, 'package.json'), 'utf8')); }
    catch (error) { if (error.code !== 'ENOENT') throw error; }
    lines.push(`## ${folder}`, '');
    if (manifest) {
      lines.push(`Workspace: \`${manifest.name}\`. Scripts: ${Object.entries(manifest.scripts ?? {}).map(([key, value]) => `\`${key}: ${value}\``).join('; ')}.`, '');
    } else {
      lines.push(entry.name === 'tts-service'
        ? 'Python adapter outside npm workspaces. Import/configuration is stdlib-only; explicit main startup loads the configured optional backend. Routine tests inject synthesis and reject model imports.'
        : group === 'packages' ? 'Schema/document collection without an npm manifest; not a participating workspace.'
        : 'No npm manifest: not a participating workspace. README responsibilities may be planned rather than implemented.', '');
    }
    for (const candidate of ['src/index.ts', 'src/config.ts', 'src/db.ts', 'src/session-authority.ts', 'src/session-http.ts', 'src/projections.ts', 'src/table-read-routes.ts', 'src/session-summary.ts', 'src/state-events.ts', 'src/state-event-routes.ts', 'src/character-routes.ts', 'src/ttrpg-action-routes.ts', 'src/narration.ts', 'src/speech.ts', 'src/backups.ts', 'src/asset-delivery.ts', 'src/media-router-client.ts', 'src/scene-images.ts', 'src/capability-health.ts', 'src/ai-adapter.ts', 'src/App.tsx', 'tts_server.py']) {
      let source;
      try { source = await readFile(resolve(root, folder, candidate), 'utf8'); }
      catch (error) { if (error.code === 'ENOENT') continue; throw error; }
      lines.push(`### ${candidate}`, '');
      const patterns = [/app\.(?:get|post|put|patch|delete|use)\(/, /(?:wss|socket)\.on\(/,
        /request\.method|url\.pathname/, /message\.type|type: "connected"/,
        /^@app\.|^def |Kokoro\(/,
        /broadcast\(/, /setInterval\(|setTimeout\(|fetch\(/, /export (?:async )?function /];
      const matches = source.split(/\r?\n/).flatMap((line, index) => patterns.some(pattern => pattern.test(line))
        ? [`- L${index + 1}: \`${line.trim().replaceAll('`', "'")}\``] : []);
      lines.push(...(matches.length ? matches : ['No matching route/timer/export markers.']), '');
    }
  }
}
lines.push('## Repository scripts', '');
for (const filename of (await readdir(resolve(root, 'scripts'))).sort()) {
  if (/\.(?:js|mjs|bat|ps1)$/.test(filename)) lines.push(`- \`scripts/${filename}\` (inspect before running; download/generation helpers are not routine checks).`);
}
lines.push('', '## Startup and side-effect review', '',
  '- `start-session.bat` delegates to the portable full-profile launcher, preserving the configured/default database. Optional Node children are explicit; no external models/tools start. Tests always override data paths and own their children. Five historical helpers were retired after caller review; see docs/script-retirement.md.',
  '- The executable game-server entrypoint explicitly opens SQLite; importing db.ts does not open/configure storage. The lifecycle owner manages recurring work and bounded shutdown. Tests inject connections or select disposable startup paths.',
  '- SQLite defaults to repo `_data/black-dice-engine.db`; tests must set a disposable `BDE_DB_PATH` before starting the entrypoint. Schema inspection precedes WAL/FULL and transactional additive migrations; see docs/schema-migrations.md.',
  '- Exports default to `_exports` and tests override them. Media serving requires approved records, session/audience checks and canonical containment in configured roots. No directory listing or arbitrary filename route remains. Tests use only owned synthetic files.',
  '- HTTP and WebSocket credentials now bind to the persisted session authority. Declared roles grant no authority. Projections filter snapshots, broadcasts, non-host exports and runtime diagnostics.',
  '- Legacy, authority and command repositories share the versioned migration runner. The first room writes its host key beside the configured database; tests use only disposable files.',
  '- CommandStore retains the latest 5000 commit metadata envelopes globally at startup/commit. Exact receipts/checkpoints remain durable; recent UI logs and retained envelopes are incomplete history. See docs/command-history.md.',
  '- Table read routes and pure summary formatting are extracted from index. GET `/api/rolls` preserves its compact response; its formerly unreachable duplicate is removed. Full records remain in projected snapshots/frames; POST rolls retain the command boundary.',
  '- AI calls happen on invocation, not import. Tests must stub optional calls and avoid inherited private provider configuration.',
  '- Runtime backup operations forward host credentials to the game-server database owner. Online SQLite snapshots publish versioned checksummed manifests; validation is read-only, and restore rehearsals use disposable copies. Automatic session policy remains open. This inventory never opens a database or backup.', '');
const output = resolve(root, 'docs/source-inventory.md');
await writeFile(output, `${lines.join('\n')}\n`);
console.log(`Wrote ${relative(root, output)} (static source only).`);
